```js
const path = require('path');

const webpack = require('webpack');
const CleanWebpackPlugin = require('clean-webpack-plugin');
const compress = require('koa-compress');
const convert = require('koa-connect');
const HtmlWebpackPlugin = require('html-webpack-plugin');
const MiniCssExtractPlugin = require('mini-css-extract-plugin');
const proxy = require('http-proxy-middleware');


const staticDir = path.resolve(__dirname, 'app', 'src');
const appRoot = path.resolve(staticDir, 'modules');
const distDir = path.resolve(__dirname, 'app', 'dist');

const DEV_MODE = process.env.WEBPACK_SERVE;

let cssLoader = [
    MiniCssExtractPlugin.loader,
    { loader: 'css-loader', options: { importLoaders: 1, sourceMap: true } },
    { loader: 'postcss-loader', options: { sourceMap: true } }
];

module.exports = {
    entry: path.resolve(appRoot, 'app.module.js'),
    output: {
        filename: devProdOption('[name].bundle.js', '[name].[chunkhash].bundle.js'),
        path: distDir,
    },
    mode: devProdOption('development', 'production'),
    devtool: devProdOption('eval-source-map', 'source-map'),
    serve: {
        host: '0.0.0.0',
        port: 8000,
        add: app => {
            app.use(compress());
            app.use(convert(proxy('/api', { target: 'http://localhost:8080' })));
            app.use(convert(proxy('/stomp', { target: 'http://localhost:8080', ws: true })));
        }
    },
    plugins: [
        prodPlugin(new CleanWebpackPlugin([distDir])),
        new HtmlWebpackPlugin({
            template: path.resolve(staticDir, 'index.html'),
            favicon: path.resolve(staticDir, 'favicon.ico')
        }),
        prodPlugin(new MiniCssExtractPlugin({ filename: '[name].[contenthash].css' })),
    ],
    optimization: {
        runtimeChunk: true,
        splitChunks: {
            chunks: 'all'
        }
    },
    module: {
        rules: [
            { test: /\.js$/, use: 'babel-loader?cacheDirectory', include: appRoot },
            { test: /\.html$/, use: 'html-loader' },
            { test: /\.css$/, use: devProdOption(['style-loader', 'css-loader'], cssLoader) },
        ]
    }
};

function devProdOption(dev, prod) {
    return DEV_MODE ? dev : prod;
}

function devPlugin(plugin) {
    return DEV_MODE ? plugin : () => {};
}

function prodPlugin(plugin) {
    return !DEV_MODE ? plugin : () => {};
}
```

But note that this config is called via webpack and not via webpack-serve.
